predicted_answer:
import json

from aind_data_access_api.document_db import MetadataDbClient

API_GATEWAY_HOST = "api.allenneuraldynamics-test.org"
DATABASE = "metadata_vector_index"
COLLECTION = "static_eval_data_assets_3_14"

docdb_api_client = MetadataDbClient(
    host=API_GATEWAY_HOST,
    database=DATABASE,
    collection=COLLECTION,
)

# Aggregation pipeline to find experiments where animal weight decreased by more than 10% between consecutive procedures
agg_pipeline = [
    # Match documents that have procedures with subject_procedures
    {
        "$match": {
            "procedures": {"$exists": True},
            "procedures.subject_procedures": {"$exists": True, "$ne": []}
        }
    },
    # Project only the needed fields
    {
        "$project": {
            "name": 1,
            "subject_id": "$subject.subject_id",
            "procedures": "$procedures.subject_procedures"
        }
    },
    # Unwind the procedures array to work with individual procedures
    {
        "$unwind": "$procedures"
    },
    # Match only procedures that have both weight measurements
    {
        "$match": {
            "procedures.animal_weight_prior": {"$exists": True, "$ne": None},
            "procedures.animal_weight_post": {"$exists": True, "$ne": None}
        }
    },
    # Project and convert weight values to numbers
    {
        "$project": {
            "name": 1,
            "subject_id": 1,
            "procedure_type": "$procedures.procedure_type",
            "start_date": "$procedures.start_date",
            "weight_prior": {"$toDouble": "$procedures.animal_weight_prior"},
            "weight_post": {"$toDouble": "$procedures.animal_weight_post"},
            "weight_unit": "$procedures.weight_unit"
        }
    },
    # Calculate weight change percentage
    {
        "$project": {
            "name": 1,
            "subject_id": 1,
            "procedure_type": 1,
            "start_date": 1,
            "weight_prior": 1,
            "weight_post": 1,
            "weight_unit": 1,
            "weight_change_pct": {
                "$multiply": [
                    {"$divide": [{"$subtract": ["$weight_post", "$weight_prior"]}, "$weight_prior"]},
                    100
                ]
            }
        }
    },
    # Filter for weight decreases greater than 10%
    {
        "$match": {
            "weight_change_pct": {"$lt": -10}
        }
    },
    # Sort by weight change percentage (ascending to show largest decreases first)
    {
        "$sort": {"weight_change_pct": 1}
    },
    # Limit results
    {
        "$limit": 20
    }
]

result = docdb_api_client.aggregate_docdb_records(
    pipeline=agg_pipeline
)
print(json.dumps(result[:10], indent=3))  # limit output to first 10 results

