import json

from aind_data_access_api.document_db import MetadataDbClient

API_GATEWAY_HOST = "api.allenneuraldynamics-test.org"
DATABASE = "metadata_vector_index"
COLLECTION = "static_eval_data_assets_3_14"

docdb_api_client = MetadataDbClient(
    host=API_GATEWAY_HOST,
    database=DATABASE,
    collection=COLLECTION,
)

# Aggregation pipeline to find modalities for 'U19 Thalamus in the Middle' project
agg_pipeline = [
    {
        "$match": {
            "data_description.project_name": {
                "$regex": "Thalamus in the [Mm]iddle", 
                "$options": "i"
            }
        }
    },
    {
        "$project": {
            "modality": "$data_description.modality",
            "_id": 0
        }
    }
]

result = docdb_api_client.aggregate_docdb_records(
    pipeline=agg_pipeline
)

# Process the results to extract unique modality names
# Since modality is a list of objects, we need to extract the name from each object
unique_modalities = set()
for doc in result:
    if "modality" in doc and doc["modality"]:
        # Handle the case where modality is a list of objects
        for modality_obj in doc["modality"]:
            if isinstance(modality_obj, dict) and "name" in modality_obj:
                unique_modalities.add(modality_obj["name"])

print("Modalities for 'U19 Thalamus in the Middle' project:")
for modality in sorted(unique_modalities):
    print(f"- {modality}")

target_python:
import json
from aind_data_access_api.document_db import MetadataDbClient

docdb_api_client = MetadataDbClient(
    host=API_GATEWAY_HOST,
    database=DATABASE,
    collection=COLLECTION,
)

agg_pipeline = [
    {
        "$match": {
            "data_description.modality": {"$exists": True, "$ne": []},
            "subject.subject_id": {"$exists": True, "$ne": None}
        }
    },
    {
        "$project": {
            "subject_id": "$subject.subject_id",
            "modalities": "$data_description.modality.name"
        }
    },
    {"$unwind": "$modalities"},
    {
        "$group": {
            "_id": {"subject_id": "$subject_id", "modality": "$modalities"}
        }
    },
    {
        "$group": {
            "_id": "$_id.subject_id",
            "unique_modalities": {"$addToSet": "$_id.modality"},
            "modality_count": {"$sum": 1}
        }
    },
    {
        "$match": {
            "modality_count": {"$gte": 3}
        }
    },
    {
        "$project": {
            "_id": 0,
            "subject_id": "$_id",
            "unique_modalities": 1,
            "modality_count": 1
        }
    },
    {"$sort": {"modality_count": -1}},
    {"$limit": 5}
]

result = docdb_api_client.aggregate_docdb_records(pipeline=agg_pipeline)
print(json.dumps(result, indent=2))

