predicted_python:
import json

from aind_data_access_api.document_db import MetadataDbClient

API_GATEWAY_HOST = "api.allenneuraldynamics-test.org"
DATABASE = "metadata_vector_index"
COLLECTION = "static_eval_data_assets_3_14"

docdb_api_client = MetadataDbClient(
    host=API_GATEWAY_HOST,
    database=DATABASE,
    collection=COLLECTION,
)

# First, get all unique instrument IDs from the instrument collection
agg_pipeline_instruments = [
    {
        "$match": {
            "instrument.instrument_id": {"$exists": True, "$ne": None}
        }
    },
    {
        "$group": {
            "_id": "$instrument.instrument_id"
        }
    }
]

instrument_ids_result = docdb_api_client.aggregate_docdb_records(
    pipeline=agg_pipeline_instruments
)

# Extract the instrument IDs into a list
valid_instrument_ids = [doc["_id"] for doc in instrument_ids_result]
print(f"Found {len(valid_instrument_ids)} valid instrument IDs in the database")

# Now find all experiments where acquisition.instrument_id exists but doesn't match any valid instrument IDs
filter_query = {
    "acquisition.instrument_id": {"$exists": True, "$ne": None, "$nin": valid_instrument_ids}
}

projection = {
    "name": 1,
    "acquisition.instrument_id": 1,
    "_id": 0
}

mismatched_records = docdb_api_client.retrieve_docdb_records(
    filter_query=filter_query,
    projection=projection,
)

print(f"\nFound {len(mismatched_records)} experiments with mismatched instrument IDs:")
print(json.dumps(mismatched_records, indent=3))

target_python:
from aind_data_access_api.document_db import MetadataDbClient

docdb_api_client = MetadataDbClient(
    host=API_GATEWAY_HOST,
    database=DATABASE,
    collection=COLLECTION,
)


agg_pipeline = [
    {
        "$match": {
            "data_description.modality.name": "Selective plane illumination microscopy"
        }
    },
    {
        "$project": {
            "instrument_id": "$instrument.instrument_id"
        }
    },
    {
        "$group": {
            "_id": "$instrument_id"
        }
    },
    {
        "$sort": {
            "_id": 1
        }
    }
]

result = docdb_api_client.aggregate_docdb_records(
    pipeline=agg_pipeline
)

# Print unique instrument IDs, excluding null values
unique_instrument_ids = [record['_id'] for record in result if record['_id'] is not None]
print("Unique SmartSPIM Instrument IDs:")
for instrument_id in unique_instrument_ids:
    print(instrument_id)

print(f"\nTotal unique instrument IDs: {len(unique_instrument_ids)}")

