import json

from aind_data_access_api.document_db import MetadataDbClient

API_GATEWAY_HOST = "api.allenneuraldynamics-test.org"
DATABASE = "metadata_vector_index"
COLLECTION = "static_eval_data_assets_3_14"

docdb_api_client = MetadataDbClient(
    host=API_GATEWAY_HOST,
    database=DATABASE,
    collection=COLLECTION,
)

# Aggregation pipeline to find animals in the "Thalamus in the Middle" project
# with injections at coordinates AP: 2.8, ML: 0.2, DV: 0.6
agg_pipeline = [
    {
        "$match": {
            "data_description.project_name": {"$regex": "Thalamus in the middle", "$options": "i"},
            "procedures.subject_procedures": {
                "$elemMatch": {
                    "procedures": {
                        "$elemMatch": {
                            "procedure_type": {"$regex": "injection", "$options": "i"},
                            "injection_coordinate_ap": "2.8",
                            "injection_coordinate_ml": "0.2",
                            "injection_coordinate_depth": {"$in": ["0.6"]}
                        }
                    }
                }
            }
        }
    },
    {
        "$project": {
            "_id": 1,
            "subject_id": "$subject.subject_id",
            "project_name": "$data_description.project_name",
            "injection_details": {
                "$filter": {
                    "input": {
                        "$reduce": {
                            "input": "$procedures.subject_procedures",
                            "initialValue": [],
                            "in": {
                                "$concatArrays": [
                                    "$$value",
                                    {
                                        "$filter": {
                                            "input": "$$this.procedures",
                                            "as": "proc",
                                            "cond": {
                                                "$and": [
                                                    {"$regexMatch": {"input": {"$ifNull": ["$$proc.procedure_type", ""]}, "regex": "injection", "options": "i"}},
                                                    {"$eq": ["$$proc.injection_coordinate_ap", "2.8"]},
                                                    {"$eq": ["$$proc.injection_coordinate_ml", "0.2"]},
                                                    {"$in": ["0.6", {"$ifNull": ["$$proc.injection_coordinate_depth", []]}]}
                                                ]
                                            }
                                        }
                                    }
                                ]
                            }
                        }
                    },
                    "as": "item",
                    "cond": {"$ne": ["$$item", []]}
                }
            }
        }
    },
    {
        "$group": {
            "_id": None,
            "count": {"$sum": 1},
            "subject_ids": {"$addToSet": "$subject_id"}
        }
    },
    {
        "$project": {
            "_id": 0,
            "count": 1,
            "subject_ids": 1
        }
    }
]

result = docdb_api_client.aggregate_docdb_records(
    pipeline=agg_pipeline
)
print(json.dumps(result, indent=3))

