COLLECTION = "static_eval_data_assets_3_14"

docdb_api_client = MetadataDbClient(
    host=API_GATEWAY_HOST,
    database=DATABASE,
    collection=COLLECTION,
)

# First, let's examine the structure of a document to understand how virus names are stored
sample_doc = docdb_api_client.retrieve_docdb_records(
    filter_query={
        "data_description.project_name": "Thalamus in the middle",
        "procedures.subject_procedures.procedures.targeted_structure": "VM"
    },
    limit=1
)

# Print the structure of procedures to understand the correct path to virus names
print("Sample document structure for procedures:")
if sample_doc and len(sample_doc) > 0:
    if "procedures" in sample_doc[0]:
        print(json.dumps(sample_doc[0]["procedures"], indent=3))
    else:
        print("No procedures field found in the document")
else:
