    host=API_GATEWAY_HOST,
    database=DATABASE,
    collection=COLLECTION,
)

# Aggregation pipeline to find subjects with sessions containing both optical physiology and behavior data streams
agg_pipeline = [
    # First, filter for documents that have session data
    {"$match": {"session": {"$exists": True}}},

    # Unwind the data_streams array to examine each stream
    {"$unwind": "$session.data_streams"},

    # Group by subject_id and collect the unique data stream types
    {"$group": {
        "_id": "$subject.subject_id",
        "data_stream_types": {"$addToSet": "$session.data_streams.data_stream_type"}
    }},

    # Filter for subjects that have both optical physiology and behavior data streams
    {"$match": {
        "$and": [
            {"data_stream_types": "optical_physiology"},
            {"data_stream_types": "behavior"}
        ]
    }},

    # Count the number of subjects
    {"$count": "subjects_with_both_streams"}
]

result = docdb_api_client.aggregate_docdb_records(
    pipeline=agg_pipeline
)

print(json.dumps(result, indent=3))

