            "unique_investigators": {"$addToSet": "$investigators"},
            "count": {"$sum": 1}
        }
    },
    # Project the results with more readable field names
    {
        "$project": {
            "project_name": "$_id",
            "investigator_count": {"$size": "$unique_investigators"},
            "investigators": "$unique_investigators"
        }
    },
    # Sort by investigator count in descending order
    {
        "$sort": {
            "investigator_count": -1
        }
    },
    # Limit to top 10 results
    {
        "$limit": 10
    }
]

result = docdb_api_client.aggregate_docdb_records(
