import json

from aind_data_access_api.document_db import MetadataDbClient

API_GATEWAY_HOST = "api.allenneuraldynamics-test.org"
DATABASE = "metadata_vector_index"
COLLECTION = "static_eval_data_assets_3_14"

docdb_api_client = MetadataDbClient(
    host=API_GATEWAY_HOST,
    database=DATABASE,
    collection=COLLECTION,
)

# First, find the experimenter who has conducted the most sessions in SmartSPIM modality
pipeline_most_sessions = [
    # Match documents with SmartSPIM modality
    {"$match": {
        "data_description.modality.name": "Selective plane illumination microscopy",
        "acquisition.experimenter_full_name": {"$exists": True}
    }},
    # Unwind the experimenter array to count individual experimenters
    {"$unwind": "$acquisition.experimenter_full_name"},
    # Group by experimenter and count sessions
    {"$group": {
        "_id": "$acquisition.experimenter_full_name",
        "count": {"$sum": 1},
        "session_ids": {"$addToSet": "$_id"}
    }},
    # Sort by count in descending order
    {"$sort": {"count": -1}},
    # Limit to the top experimenter
    {"$limit": 1}
]

top_experimenter_result = docdb_api_client.aggregate_docdb_records(
    pipeline=pipeline_most_sessions
)

# Extract the top experimenter's name
if top_experimenter_result:
    top_experimenter = top_experimenter_result[0]["_id"]
    session_count = top_experimenter_result[0]["count"]
    print(f"Top experimenter for SmartSPIM sessions: {top_experimenter}")
    print(f"Number of sessions conducted: {session_count}")

    # Now find all unique instruments used by this experimenter in SmartSPIM sessions
    pipeline_instruments = [
        # Match documents with SmartSPIM modality and the top experimenter
        {"$match": {
            "data_description.modality.name": "Selective plane illumination microscopy",
            "acquisition.experimenter_full_name": top_experimenter,
            "acquisition.instrument_name": {"$exists": True}
        }},
        # Group to get unique instruments and when they were used
        {"$group": {
            "_id": "$acquisition.instrument_name",
            "first_used": {"$min": "$acquisition.session_start_time"},
            "last_used": {"$max": "$acquisition.session_start_time"},
            "session_count": {"$sum": 1}
        }},
        # Sort by first used date
        {"$sort": {"first_used": 1}}
    ]

    instruments_result = docdb_api_client.aggregate_docdb_records(
        pipeline=pipeline_instruments
    )

    print("\nUnique instruments used by this experimenter over time:")
    for instrument in instruments_result:
        print(f"Instrument: {instrument['_id']}")
        print(f"  First used: {instrument['first_used']}")
        print(f"  Last used: {instrument['last_used']}")
        print(f"  Sessions: {instrument['session_count']}")
        print("---")
else:
    print("No SmartSPIM sessions found with experimenter information.")

